describe('Password Reset Confirmation', () => {
    beforeEach(() => {
        cy.visit('/reset-password');
    });

    it('should display a confirmation message after successful password reset', () => {
        cy.get('input[name="email"]').type('user@example.com');
        cy.get('button[type="submit"]').click();
        cy.contains('A confirmation link has been sent to your email.').should('be.visible');
    });

    it('should not display a confirmation message when email is not provided', () => {
        cy.get('button[type="submit"]').click();
        cy.contains('Please enter your email address.').should('be.visible');
    });
});
